#!/usr/bin/env bash
# Applies כדורגלן's customizations to the Android project generated by `npx cap add android`.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.01}"
APP=android/app
RES=$APP/src/main/res

# 1) Icons and splash
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) Permissions: network state (content updates), vibration, installing the new version of the app
#    (every update is a full APK), and saving the APK to the phone's Documents folder on Android 10 and older.
MAN=$APP/src/main/AndroidManifest.xml
perl -0pi -e 's|</manifest>|    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n    <uses-permission android:name="android.permission.VIBRATE" />\n    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES" />\n    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29" />\n    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32" />\n</manifest>|' "$MAN"
perl -0pi -e 's|<application |<application android:requestLegacyExternalStorage="true" |' "$MAN"

# 3) Dark splash with the ball on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#060A12</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 4) Target SDK 34 (classic status bar; the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 5) Version: code is the build number (every APK installs as an update), and the name carries the build too,
#    so a file manager's app backup shows exactly which version it saved.
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}.${RUN}\"/" "$APP/build.gradle"

# 6) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        kaduraglan {
            storeFile file("release.jks")
            storePassword System.getenv("KG_STORE_PASSWORD")
            keyAlias System.getenv("KG_KEY_ALIAS")
            keyPassword System.getenv("KG_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.kaduraglan
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest permissions"; grep -n 'uses-permission\|requestLegacy' "$MAN"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n targetSdk android/variables.gradle
